import { createSlice, PayloadAction } from "@reduxjs/toolkit";

interface SentState {
  inbox_data: any;
}

const initialState: SentState = {
  inbox_data: {
    SUBJECT: "CERTIFI Secure Electronic Communication for Galgotia University ",
    TO: "director@galgotiacollege.edu.in",
    BODY: "Dear Sir,I hope you are doing well.First of all, thank you for giving us the opportunity to present CERTIFI to you on 11 February 2026.As per your suggestion, please find attached our detailed proposal for implementing CERTIFI within your institution’s electronic communications, enabling secure, tamper‑proof, and legally admissible proof of every Critical interaction.Why CERTIFI for an Educational Institution?Educational institutions routinely exchange sensitive electronic communications—admission confirmations, fee notices, academic records, examination‑related messages, vendor agreements, and regulatory correspondence. CERTIFI is purpose‑built to add authenticity, integrity, and verifiable certificate for further use to all such official communications, thereby:Reducing the risk of disputes, miscommunication, Denial of communication and  fraudStrengthening governance, compliance, and record integrityEnhancing institutional credibility and trust with students, parents, staff, and regulatory authorities.The Attached Proposal Includes• Sector-specific use cases• Detailed platform features and security framework• Deployment approach and implementation model• Commercial structure and scopeWe are confident that CERTIFI will fortify your institution’s communication processes and support its strategic objectives.Kindly review the attached document at your convenience and let us know a suitable time for a further detailed discussion. We would be happy to answer any questions/clarification, explore customisationoptions, and align the solution with your specific requirements.Thank you once again for your time and consideration. I look forward to connecting with you soon.Warm regards,Anand SinghSales Executive+91 8882847128LinkedInInstagramYouTube",
    FROM: "asingh01@synerthinksolutions.com",
    TIME: "2026-02-24, 11:42:23",
    ATTACH: [
      {
        unicode_name: "CERTIFI Proposal Document Galgotias university  (1).pdf",
        filename: "CERTIFI Proposal Document Galgotias university  (1).pdf",
        title: "CERTIFI Proposal Document Galgotias university  (1).pdf",
        ctype: "application/pdf",
        cset: "base64",
        data: "",
        disposition: "",
        cid: "",
      },
    ],
    response: "ok",
  },
};

type SetFieldPayload<K extends keyof SentState> = {
  name: K;
  value: SentState[K];
};

export const sentSlice = createSlice({
  name: "sent",
  initialState,
  reducers: {
    inboxSetFields<K extends keyof SentState>(
      state: any,
      action: PayloadAction<SetFieldPayload<K>>,
    ) {
      state[action.payload.name] = action.payload.value;
    },
    inboxResetFields: (state) => {
      state.inbox_data = {};
    },
  },
});

export const { inboxSetFields, inboxResetFields } = sentSlice.actions;
export default sentSlice.reducer;
